using System;using System.Linq;using System.Drawing;using System.Reflection;using System.Windows.Forms;
class MainQuestChecks{[STAThread]static void Main(){Application.EnableVisualStyles();using(var game=new Game()){game.Opacity=0;game.Show();var save=new Save();save.completed.Add(TavernStory.Id);typeof(Game).GetField("save",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(game,save);int step=0;var timer=new Timer{Interval=250};timer.Tick+=(s,e)=>{var dialog=Application.OpenForms.OfType<GuildWordDialog>().FirstOrDefault();if(dialog==null)return;var panel=dialog.Controls.OfType<Panel>().First();var cards=panel.Controls.OfType<MainQuestCard>().ToArray();if(step==0){if(cards.Length!=7)throw new Exception("Chapter count");using(var b=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(b,dialog.ClientRectangle);b.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"main-quest-chapters.png"));}cards.First(c=>c.Heading.StartsWith("第一章")).PerformClick();step++;}else{cards=panel.Controls.OfType<MainQuestCard>().ToArray();if(cards.Length!=6||cards.Any(c=>c.Bottom>panel.Height-44))throw new Exception("Section layout");using(var b=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(b,dialog.ClientRectangle);b.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"main-quest-sections.png"));}timer.Stop();dialog.Close();}};timer.Start();typeof(Game).GetMethod("ShowTavernMainQuest",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(game,null);timer.Dispose();game.Close();}Console.WriteLine("PASS chapter cards, section navigation, layout and no scrolling.");}}
